INSERT INTO `site_content` (`id`, `content_key`, `content_value`, `updated_at`) VALUES (1,'hero_label','Cafetería · Valencia','2026-04-22 14:02:04'),(2,'hero_h1','Functional coffee<br>&amp; smart food','2026-04-22 14:02:04'),(3,'hero_subtitle','Come como piensas.<br>Comida adaptada a las necesidades de tu día.','2026-04-22 14:02:04'),(4,'qs_label','¿Quiénes somos?','2026-04-22 07:44:28'),(5,'qs_h2','Del alto rendimiento<br>a tu mesa.','2026-04-22 07:44:28'),(6,'qs_p1','TUOI es mucho más que una cafetería: es tu lugar para disfrutar, cuidarte y sentirte bien. Un espacio donde puedes hacer una pausa, empezar el día o recargar energía mientras disfrutas de un buen café y comida saludable, rica y pensada para tu día a día.','2026-04-22 07:44:28'),(7,'qs_p2','Aquí cuidarte no es complicado. Es natural, accesible… y apetecible. Detrás de TUOI está el conocimiento de <strong><a href=\"https://miobiosport.com/\" target=\"_blank\">MIOBIO</a></strong>, especialistas en alimentación funcional aplicada al deporte de élite. Toda esa experiencia se traduce en algo muy simple: ofrecerte opciones que no solo te gustan, sino que te ayudan a tener más energía, sentirte mejor y mantener tu ritmo.','2026-04-22 07:44:28'),(8,'fil_label','Nuestra filosofía','2026-04-22 07:19:34'),(9,'fil_h2','Todo bajo una misma filosofía:<br>alimentación funcional, equilibrada y con sabor.','2026-04-22 07:19:34'),(10,'card_balance_title','Nutrición en equilibrio','2026-04-22 07:19:34'),(11,'card_balance_desc','Cada plato diseñado para darte lo que necesitas, sin excesos ni carencias. Nutrición real en cada bocado.','2026-04-22 07:19:34'),(12,'card_energy_title','Activa tu mañana','2026-04-22 07:19:34'),(13,'card_energy_desc','Desayunos pensados para despertar tu rendimiento desde la primera hora del día. Sin estimulantes artificiales.','2026-04-22 07:19:34'),(14,'card_focus_title','Concentración sostenida','2026-04-22 07:19:34'),(15,'card_focus_desc','Sin picos de azúcar, sin bajones a media tarde. Comida que mantiene tu mente activa cuando más lo necesitas.','2026-04-22 07:19:34'),(16,'card_power_title','Rinde al máximo','2026-04-22 07:19:34'),(17,'card_power_desc','Proteínas, carbohidratos y grasas en su justa medida para que tu cuerpo funcione a pleno rendimiento, siempre.','2026-04-22 07:19:34'),(18,'value1','Desayunos enfocados en activar la energía','2026-04-22 07:19:34'),(19,'value2','Almuerzos diseñados para sostener el rendimiento','2026-04-22 07:19:34'),(20,'value3','Comidas orientadas a la recuperación','2026-04-22 07:19:34'),(21,'value4','Opciones adaptadas a diferentes necesidades nutricionales','2026-04-22 07:19:34'),(30,'hero_label_en','Coffee Shop - Valencia','2026-04-22 13:07:01'),(31,'hero_h1_en','Functional coffee<br>&amp; smart food','2026-04-22 13:07:01'),(32,'hero_subtitle_en','Eat the way you think.<br>Food tailored to the needs of your day.','2026-04-22 13:07:01'),(36,'qs_label_en','About Us','2026-04-22 13:09:37'),(37,'qs_h2_en','From high performance<br>to your table.','2026-04-22 13:09:37'),(38,'qs_p1_en','TUOI is much more than a café: it’s your place to enjoy, take care of yourself, and feel good. A space where you can pause, start your day, or recharge while enjoying great coffee and healthy, delicious food designed for your everyday life.','2026-04-22 13:09:37'),(39,'qs_p2_en','Taking care of yourself here isn’t complicated. It’s natural, accessible… and appealing. Behind TUOI is the expertise of <strong><a href=\"https://miobiosport.com/\" target=\"_blank\">MIOBIO</a></strong>, specialists in functional nutrition applied to elite sports. All that experience is translated into something very simple: offering you options that not only taste good, but also help you feel more energized, feel better, and keep up with your pace.','2026-04-22 13:09:37'),(40,'fil_label_en','Our philosophy','2026-04-22 13:19:07'),(41,'fil_h2_en','Everything guided by a single philosophy:<br>functional, balanced, and flavorful nutrition.','2026-04-22 13:19:07'),(42,'card_balance_title_en','Balanced nutrition','2026-04-22 13:19:07'),(43,'card_balance_desc_en','Every dish is designed to give you exactly what you need—no excess, no deficiencies. Real nutrition in every bite.','2026-04-22 13:19:07'),(44,'card_energy_title_en','Activate your morning','2026-04-22 13:19:07'),(45,'card_energy_desc_en','Breakfasts crafted to boost your performance from the very start of the day. No artificial stimulants.','2026-04-22 13:19:07'),(46,'card_focus_title_en','Sustained focus','2026-04-22 13:19:07'),(47,'card_focus_desc_en','No sugar spikes, no mid-afternoon crashes. Food that keeps your mind sharp when you need it most.','2026-04-22 13:19:07'),(48,'card_power_title_en','Perform at your best','2026-04-22 13:19:07'),(49,'card_power_desc_en','Proteins, carbohydrates, and fats in the right balance so your body operates at peak performance—always.','2026-04-22 13:19:07'),(50,'value1_en','Breakfasts focused on boosting energy','2026-04-22 13:19:07'),(51,'value2_en','Lunches designed to sustain performance','2026-04-22 13:19:07'),(52,'value3_en','Meals aimed at recovery','2026-04-22 13:19:08'),(53,'value4_en','Options tailored to different nutritional needs','2026-04-22 13:19:08'),(60,'qs_page_hero_label','Nuestra historia','2026-04-28 11:15:14'),(61,'qs_page_hero_sub','Nutrición funcional, de alto rendimiento, <br> adaptada a tu día a día.','2026-04-28 11:15:14'),(62,'qs_page_hero_h1','¿Quiénes somos?','2026-04-28 11:15:14'),(63,'qs_page_b1_label','Quiénes somos','2026-04-28 11:15:14'),(64,'qs_page_b1_h2','Tu lugar para cuidarte sin complicaciones','2026-04-28 11:15:14'),(65,'qs_page_b1_p1','TUOI es mucho más que una cafetería: es tu lugar para disfrutar, cuidarte y sentirte bien.','2026-04-28 11:15:14'),(66,'qs_page_b1_p2','Un espacio donde puedes hacer una pausa, empezar el día o recargar energía mientras disfrutas de café y comida saludable, rica y pensada para tu día a día.','2026-04-28 11:15:14'),(67,'qs_page_b1_p3','Aquí cuidarte no es complicado. Es natural, accesible… y apetecible.','2026-04-28 11:15:14'),(68,'qs_page_b2_label','Nuestro origen','2026-04-28 11:15:14'),(69,'qs_page_b2_h2','El conocimiento del deporte de élite, en tu mesa','2026-04-28 11:15:14'),(70,'qs_page_b2_p1','Detrás de TUOI está el conocimiento de <strong><a href=\"https://miobiosport.com/\" target=\"_blank\">MIOBIO</a></strong>, especialistas en alimentación funcional aplicada al deporte de élite. Toda esa experiencia se traduce en algo muy simple: ofrecerte opciones que no solo te gustan, sino que te ayudan a tener más energía, sentirte mejor y mantener tu ritmo.','2026-04-28 11:15:14'),(71,'qs_page_b2_p2','Porque lo que comes influye en cómo te sientes.','2026-04-28 11:15:14'),(72,'qs_page_b3_label','Nuestra propuesta','2026-04-28 11:15:14'),(73,'qs_page_b3_h2','En TUOI puedes:','2026-04-28 11:15:14'),(74,'qs_page_b3_intro','','2026-04-28 11:15:14'),(75,'qs_page_b3_li1','Empezar el día con desayunos que activan tu energía','2026-04-28 11:15:14'),(76,'qs_page_b3_li2','Disfrutar de café y opciones saludables en cualquier momento','2026-04-28 11:15:14'),(77,'qs_page_b3_li3','Hacer una pausa con comida equilibrada que realmente apetece','2026-04-28 11:15:14'),(78,'qs_page_b3_p','Todo bajo una misma idea: comer bien sin complicarte.','2026-04-28 11:15:14'),(79,'qs_page_close_p','TUOI es el punto de encuentro entre el conocimiento del alto rendimiento y tu día a día. <strong>Un lugar donde lo saludable se convierte en parte natural de tu rutina.</strong>','2026-04-28 11:15:14'),(80,'qs_page_close_btn','Explorar la carta','2026-04-28 11:15:14'),(102,'qs_page_hero_label_en','Our story','2026-04-23 09:33:26'),(103,'qs_page_hero_sub_en','Functional, high-performance nutrition for your everyday life','2026-04-23 09:33:26'),(104,'qs_page_hero_h1_en','About us','2026-04-23 09:33:26'),(105,'qs_page_b1_label_en','Who we are','2026-04-23 09:33:26'),(106,'qs_page_b1_h2_en','Your place to take care of yourself, effortlessly.','2026-04-23 09:33:26'),(107,'qs_page_b1_p1_en','TUOI is much more than a coffee shop — it’s your place to enjoy, take care of yourself, and feel good.','2026-04-23 09:33:26'),(108,'qs_page_b1_p2_en','A space where you can pause, start your day, or recharge while enjoying coffee and healthy, delicious food designed for your everyday life.','2026-04-23 09:33:26'),(109,'qs_page_b1_p3_en','A space where you can pause, start your day, or recharge while enjoying coffee and healthy, delicious food designed for your everyday life.','2026-04-23 09:33:26'),(110,'qs_page_b2_label_en','Our origins','2026-04-23 09:33:26'),(111,'qs_page_b2_h2_en','Bringing elite sports expertise to your table.','2026-04-23 09:33:26'),(112,'qs_page_b2_p1_en','Behind TUOI is the expertise of <a href=\"https://miobiosport.com/\" target=\"_blank\">MIOBIO</a>, specialists in functional nutrition applied to elite sports. All that knowledge is translated into something very simple: offering you options that not only taste good, but also help you feel more energized, feel better, and keep up with your daily rhythm.','2026-04-23 09:33:26'),(113,'qs_page_b2_p2_en','Because feeling good begins with what you eat.','2026-04-23 09:33:26'),(114,'qs_page_b3_label_en','What we offer','2026-04-23 09:33:26'),(115,'qs_page_b3_h2_en','At TUOI, you can:','2026-04-23 09:33:26'),(116,'qs_page_b3_intro_en','','2026-04-23 09:33:26'),(117,'qs_page_b3_li1_en','Start your day with breakfasts that boost your energy','2026-04-23 09:33:26'),(118,'qs_page_b3_li2_en','Enjoy coffee and healthy options at any time','2026-04-23 09:33:26'),(119,'qs_page_b3_li3_en','Take a break with balanced meals you’ll genuinely crave','2026-04-23 09:33:26'),(120,'qs_page_b3_p_en','All under one simple idea: eating well without the hassle.','2026-04-23 09:33:26'),(121,'qs_page_close_p_en','TUOI is the meeting point between high-performance expertise and your everyday life. <strong>A place where healthy living becomes a natural part of your routine.</strong>','2026-04-23 09:33:26'),(122,'qs_page_close_btn_en','Discover our menu','2026-04-23 09:33:26'),(252,'contact_phone','+34 606 01 41 21','2026-05-11 13:54:15'),(253,'contact_email','hola@miobiosport.com','2026-05-11 13:54:15'),(254,'contact_address','C. de la Travesía, 15B, 46024 València','2026-05-11 13:54:15'),(255,'ev_why_label','La diferencia','2026-04-29 14:05:15'),(256,'ev_why_h2','Sentido en cada detalle','2026-04-29 14:05:15'),(259,'ev_why_b1_icon','🌱','2026-04-29 14:05:15'),(260,'ev_why_b1_title','Cerca, con criterio','2026-04-29 14:05:16'),(261,'ev_why_b1_desc','Proximidad, procesos cuidados y decisiones que importan.','2026-04-29 14:05:16'),(262,'ev_why_b2_icon','💚','2026-04-29 14:05:16'),(263,'ev_why_b2_title','Ligero, con carácter','2026-04-29 14:05:16'),(264,'ev_why_b2_desc','Producto real. Equilibrio, sabor y cero exceso.','2026-04-29 14:05:16'),(265,'ev_why_b3_icon','⚡','2026-04-29 14:05:16'),(266,'ev_why_b3_title','Energía constante','2026-04-29 14:05:16'),(267,'ev_why_b3_desc','Claridad, fluidez y un ritmo que se sostiene.','2026-04-29 14:05:16'),(268,'ev_why_b4_icon','🎯','2026-04-29 14:05:16'),(269,'ev_why_b4_title','A tu medida','2026-04-29 14:05:16'),(270,'ev_why_b4_desc','Cada detalle alineado con tu evento.','2026-04-29 14:05:16'),(285,'ev_menus_label','Descubre nuestros menús','2026-04-29 14:06:16'),(286,'ev_menus_h2','Menús que se viven, no solo se prueban','2026-04-29 14:06:16'),(287,'ev_menus_intro','Diseñamos cada menú para que el evento fluya: comida real, ligera y con sentido, pensada para que la gente disfrute, conecte y se acuerde.','2026-04-29 14:06:16'),(291,'ev_intro_label','Nuestra filosofía','2026-05-05 08:22:31'),(292,'ev_intro_p1','En TUOI llevamos nuestra filosofía de functional coffee & smart food también al mundo de los eventos. Diseñamos experiencias gastronómicas que no solo acompañan, sino que potencian lo que ocurre en cada encuentro: más claridad, mejor energía y una sensación real de bienestar.','2026-05-05 08:22:31'),(293,'ev_intro_p2','Trabajamos con ingredientes de proximidad y propuestas equilibradas que se adaptan al ritmo y objetivo de cada encuentro. El resultado: comida ligera, sabrosa y funcional, que favorece un rendimiento constante y acompaña el ritmo natural de cada momento.','2026-05-05 08:22:31'),(294,'ev_hero_label_en','Events · TUOI','2026-05-05 09:20:04'),(295,'ev_hero_sub_en','Culinary experiences that elevate every gathering.','2026-05-05 09:20:04'),(296,'ev_hero_h1_en','Events with meaning, energy and purpose','2026-05-05 09:20:04'),(297,'ev_intro_label_en','Our philosophy','2026-05-05 09:25:04'),(298,'ev_intro_p1_en',' At TUOI we bring our functional coffee & smart food philosophy into the world of events too. We design culinary experiences that don\'t just accompany — they amplify what happens at every gathering: more clarity, better energy and a real sense of wellbeing.','2026-05-05 09:25:04'),(299,'ev_intro_p2_en','We work with locally-sourced ingredients and balanced proposals tailored to the pace and purpose of each gathering. The result: light, flavorful and functional food that avoids energy crashes and follows the natural rhythm of every moment.','2026-05-05 09:25:04'),(300,'ev_why_label_en','Why TUOI?','2026-05-05 09:21:59'),(301,'ev_why_h2_en','','2026-05-05 09:21:59'),(302,'ev_why_b1_icon_en','','2026-05-05 09:21:59'),(303,'ev_why_b1_title_en','Local and meaningful','2026-05-05 09:21:59'),(304,'ev_why_b1_desc_en','We work with locally-sourced ingredients, responsible materials and careful processes. Because a good event shouldn\'t come at the planet\'s expense.','2026-05-05 09:21:59'),(305,'ev_why_b2_icon_en','','2026-05-05 09:21:59'),(306,'ev_why_b2_title_en','Light and real','2026-05-05 09:21:59'),(307,'ev_why_b2_desc_en','Real food, no ultra-processed ingredients, no excess. Tasty, balanced and easy to enjoy — without feeling heavy.','2026-05-05 09:21:59'),(308,'ev_why_b3_icon_en','','2026-05-05 09:21:59'),(309,'ev_why_b3_title_en','Energy that lasts','2026-05-05 09:21:59'),(310,'ev_why_b3_desc_en','We design menus so the event flows: steady energy, sharp minds and zero crashes.','2026-05-05 09:21:59'),(311,'ev_why_b4_icon_en','','2026-05-05 09:21:59'),(312,'ev_why_b4_title_en','Tailored to your event','2026-05-05 09:21:59'),(313,'ev_why_b4_desc_en','Every proposal adapts to what you need: the format, the people and the message you want to convey.','2026-05-05 09:21:59'),(314,'ev_menus_label_en','Our menus','2026-05-05 09:22:26'),(315,'ev_menus_h2_en','Menus that adapt to your event','2026-05-05 09:22:26'),(316,'ev_menus_intro_en','We offer different formats tailored to the type of gathering and the experience you want to create.','2026-05-05 09:22:26'),(326,'ev_cta_h2_en','Got an event in mind?','2026-05-05 09:23:56'),(327,'ev_cta_text_en','Tell us how you imagine it and we\'ll design the menu to fit.','2026-05-05 09:23:56'),(328,'ev_cta_btn_en','Let\'s talk →','2026-05-05 09:23:56'),(329,'ev_marquee_text_en','Networking events – Afterworks – Team buildings – Launches – Corporate or creative gatherings','2026-05-05 09:24:43'),(355,'ev_el_intro','Tres formatos pensados para acompañar cada tipo de encuentro: desde una pausa que activa, hasta una experiencia gastronómica completa.','2026-05-11 14:36:01'),(356,'ev_el_e1_tagline','La pausa perfecta para mantener la energía y el ritmo del evento.','2026-05-12 08:46:31'),(357,'ev_el_e1_body','<p><strong>Incluye:</strong></p><ul><li>Café de especialidad, infusiones, zumo de naranja natural, leche semi, sin lactosa y de avena, botellas de agua.</li><li>Mini bakery (croissant y pops de chocolate).</li><li>Mini salados: pulguitas de brie, jamón y mermelada de tomate; pavo con cremoso de aguacate; mini croissant de tomate, 4 quesos y espinacas.</li><li>Fruta.</li><li>Opciones veganas y sin gluten, bajo petición.</li></ul>','2026-05-12 08:46:31'),(358,'ev_el_e2_tagline','Mucho más que un coffee break: una experiencia diseñada para activar cuerpo y mente.','2026-05-11 14:36:01'),(359,'ev_el_e2_body','<p><strong>Incluye:</strong></p>\r\n<ul>\r\n<li>Café de especialidad, infusiones, zumo de naranja natural, leche semi, sin lactosa y de avena, botellas de agua.</li>\r\n<li>Mini croissant.</li>\r\n<li>Mini cookies.</li>\r\n<li>Mini muffins.</li>\r\n<li>Mini salados: pulguitas de brie, jamón y mermelada de tomate; pavo con cremoso de aguacate; mini croissant de tomate, 4 quesos y espinacas.</li>\r\n<li>Mini empanadillas de pisto.</li>\r\n<li>Vasito de yogurt con granola casera.</li>\r\n<li>Fruta.</li>\r\n<li>Opciones veganas y sin gluten, bajo petición.</li>\r\n</ul>','2026-05-11 14:36:01'),(360,'ev_el_e3_tagline','Una propuesta fresca y cuidada para eventos donde conectar también forma parte de la experiencia.','2026-05-11 14:36:01'),(361,'ev_el_e3_body','<p><strong>Incluye:</strong></p>\r\n<ul>\r\n<li>Bebida: cerveza, refresco o agua.</li>\r\n<li>Hojaldres de cremoso de aguacate con jamón ibérico.</li>\r\n<li>Tortilla de patata.</li>\r\n</ul>','2026-05-11 14:36:01'),(362,'ev_el_e4_tagline','Una experiencia gastronómica diseñada para sorprender, emocionar y crear recuerdo.','2026-05-11 14:36:01'),(363,'ev_el_e4_body','<p><strong>Añadir:</strong></p>\r\n<ul>\r\n<li>Showcooking.</li>\r\n<li>Estaciones en vivo.</li>\r\n<li>Maridajes funcionales.</li>\r\n<li>Mixología saludable.</li>\r\n<li>Coctelería de autor.</li>\r\n<li>Experiencias temáticas.</li>\r\n<li>Menú diseñado según el tipo de evento.</li>\r\n<li>Puesta en escena premium.</li>\r\n</ul>','2026-05-11 14:36:01'),(364,'ev_el_e5_tagline','Comida real y equilibrada para encuentros donde compartir es parte del momento.','2026-05-11 14:36:01'),(365,'ev_el_e5_body','<p><strong>Incluye:</strong></p>\r\n<ul>\r\n<li>Bowls.</li>\r\n<li>Focaccias.</li>\r\n<li>Ensaladas premium.</li>\r\n<li>Platos para compartir.</li>\r\n<li>Opciones funcionales.</li>\r\n<li>Postres saludables.</li>\r\n</ul>','2026-05-11 14:36:01'),(366,'ev_el_e6_tagline','Una experiencia gastronómica premium donde bienestar, estética y sabor se unen.','2026-05-11 14:36:01'),(367,'ev_el_e6_body','<p><strong>Añadir:</strong></p>\r\n<ul>\r\n<li>Brunch experiencial.</li>\r\n<li>Estaciones gastronómicas.</li>\r\n<li>Menú personalizado.</li>\r\n<li>Platos inspirados en nutrición deportiva.</li>\r\n<li>Showcooking.</li>\r\n<li>Menú wellness.</li>\r\n<li>Experiencia sensorial.</li>\r\n<li>Maridaje funcional.</li>\r\n<li>Diseño visual personalizado.</li>\r\n</ul>','2026-05-11 14:36:01'),(368,'ev_el_service_body','<ul><li>Opciones alimentarias adaptadas: sin gluten, sin lactosa y vegetarianas.</li><li>Uso preferente de materiales de servicio reciclables o reutilizables, reduciendo plásticos de un solo uso. Envases reutilizables o reciclables (tapers) para minimizar el desperdicio alimentario.</li><li>Transporte y logística del servicio.</li><li>Montaje y preparación del espacio.</li><li>Material de servicio: menaje, mesas auxiliares y mantelería si procede.</li><li>Personal para atención durante el servicio.</li></ul>','2026-05-13 18:40:52'),(369,'ev_el_conditions_body','<h4>Condiciones de contratación</h4>\r\n<p>El número final de comensales y el desglose de menús (vegetarianos, intolerancias alimentarias) deberá confirmarse como máximo 8 días antes de la fecha del evento. Cualquier modificación posterior estará sujeta a disponibilidad y posible ajuste presupuestario.</p>\r\n<h4>Anulaciones</h4>\r\n<p>Las anulaciones deberán realizarse exclusivamente por teléfono o correo electrónico, siendo imprescindible la confirmación expresa por parte de la empresa. No se aceptarán anulaciones en el buzón de voz. Con menos de 24 horas laborables de antelación, se cobrará el importe íntegro del pedido.</p>\r\n<p>Toda la vajilla, menaje o material atribuibles al evento será de materiales desechables y biodegradables si no se indica lo contrario. La aceptación de esta propuesta implica la plena conformidad con todas las condiciones aquí expuestas.</p>\r\n<h4>Condiciones de pago</h4>\r\n<p>Para confirmar la fecha y el servicio, será necesario realizar un anticipo del 50% del importe total, que servirá como garantía de reserva. El 50% restante se deberá abonar 48 horas antes del inicio del servicio.</p>\r\n<p>En caso de contratación con menos de 7 días de antelación, se requerirá el 100% del importe total como pago único y anticipado.</p>','2026-05-11 14:36:01'),(402,'ev_el_e1_name','Flow Coffee Essential','2026-05-12 08:46:31'),(405,'ev_el_service_label','Servicio','2026-05-13 18:40:52'),(406,'ev_el_service_h2','Todos nuestros eventos incluyen:','2026-05-13 18:40:52'),(411,'ev_hero_label','Eventos · TUOI','2026-05-18 13:21:03'),(412,'ev_hero_sub','Experiencias gastronómicas que potencian cada encuentro.','2026-05-18 13:21:03'),(413,'ev_hero_h1','Eventos con sentido, energía y propósito','2026-05-18 13:21:03'),(414,'ev_hero_cta_primary','Hablemos de tu evento','2026-05-18 13:21:03'),(415,'ev_hero_cta_secondary','Ver menús','2026-05-18 13:21:03'),(421,'ev_opt1_label_en','TUOI experiences','2026-05-25 07:34:54'),(422,'ev_opt1_cta_en','Discover Experiences','2026-05-25 07:34:54'),(423,'ev_opt1_title_en','Ready to enjoy','2026-05-25 07:34:54'),(424,'ev_opt1_desc_en','Three formats designed to suit every type of gathering. Choose yours, and we’ll take care of the rest.','2026-05-25 07:34:54'),(429,'ev_opt2_label_en','Designed for you','2026-05-25 07:39:13'),(430,'ev_opt2_title_en','Tailor-made','2026-05-25 07:39:13'),(431,'ev_opt2_desc_en','We design the menu with you, based on the format, the guests, and the experience you want to create.\r\n','2026-05-25 07:39:13'),(432,'ev_opt2_cta_primary_en','Discover your posibilities','2026-05-25 07:39:13'),(433,'ev_opt2_cta_secondary_en','Contact us','2026-05-25 07:39:13'),(434,'ig_cta_text','¿Qué hay hoy en TUOI? El menú del día se publica cada mañana en nuestro Instagram.','2026-06-15 20:50:35'),(435,'ig_cta_url','https://www.instagram.com/tuoi.coffee/','2026-06-15 20:50:35');
