INSERT INTO `testimonios` (`id`, `quote`, `quote_en`, `author`, `role`, `role_en`, `sort_order`, `active`, `created_at`) VALUES (1,'Organizar el evento con TUOI fue facilísimo. Nos ayudaron a cuidar cada detalle y se notó muchísimo en el ambiente: la gente estuvo cómoda, participativa y con energía hasta el final.',NULL,'Laura Martínez','Event Manager · Nexa Digital',NULL,2,1,'2026-04-30 11:59:24'),(2,'Buscábamos algo diferente para nuestro team building y con TUOI acertamos de lleno. La comida, la organización y el ritmo del evento hicieron que todo fluyera sin esfuerzo. Repetiremos seguro.',NULL,'Carlos Vega','HR Business Partner · Altia Tech',NULL,1,1,'2026-04-30 11:59:53'),(3,'Lo que más valoramos fue la tranquilidad de delegar en un equipo que sabe lo que hace. Todo salió según lo previsto y el feedback interno fue muy positivo, especialmente por la calidad del catering y la dinámica del evento.',NULL,'Ana Beltrán','Office Manager · Grupo Lumen',NULL,0,1,'2026-04-30 12:00:25');
/*!40000 ALTER TABLE `testimonios` ENABLE KEYS */;

